import{describe,it,expect,beforeEach}from"vitest";import{LandmarkRecognitionEngine}from"../../frontend/js-modules/landmark-recognition-engine.js";const TAJ_HASH="1111111011111111111111110001100000000000111001100000000000000000".slice(0,64),HAWA_HASH="0011111101111110011111101111111111011110110111000000000000111100",sampleLandmarks=[{id:"taj_mahal",name:"Taj Mahal",state:"Uttar Pradesh",city:"Agra",hash:TAJ_HASH,nearbyAttractions:["Agra Fort"]},{id:"hawa_mahal",name:"Hawa Mahal",state:"Rajasthan",city:"Jaipur",hash:HAWA_HASH,nearbyAttractions:["Amber Fort"]}];describe("LandmarkRecognitionEngine.hammingDistance",()=>{it("returns 0 for identical hashes",()=>{expect(LandmarkRecognitionEngine.hammingDistance("1010","1010")).toBe(0)}),it("counts differing bits",()=>{expect(LandmarkRecognitionEngine.hammingDistance("1010","0010")).toBe(1),expect(LandmarkRecognitionEngine.hammingDistance("1111","0000")).toBe(4)}),it("returns -1 for mismatched lengths or invalid input",()=>{expect(LandmarkRecognitionEngine.hammingDistance("101","10")).toBe(-1),expect(LandmarkRecognitionEngine.hammingDistance(null,"10")).toBe(-1),expect(LandmarkRecognitionEngine.hammingDistance("","")).toBe(-1)})}),describe("LandmarkRecognitionEngine.distanceToConfidence",()=>{it("gives full confidence for zero distance",()=>{expect(LandmarkRecognitionEngine.distanceToConfidence(0,64)).toBe(1)}),it("gives zero confidence for maximal distance",()=>{expect(LandmarkRecognitionEngine.distanceToConfidence(64,64)).toBe(0)}),it("scales linearly between 0 and 1",()=>{expect(LandmarkRecognitionEngine.distanceToConfidence(16,64)).toBeCloseTo(.75,5)})}),describe("LandmarkRecognitionEngine.isValidHash",()=>{it("accepts binary strings",()=>{expect(LandmarkRecognitionEngine.isValidHash("0101")).toBe(!0)}),it("rejects non-binary or empty strings",()=>{expect(LandmarkRecognitionEngine.isValidHash("abcd")).toBe(!1),expect(LandmarkRecognitionEngine.isValidHash("")).toBe(!1),expect(LandmarkRecognitionEngine.isValidHash(null)).toBe(!1)})}),describe("LandmarkRecognitionEngine#identify",()=>{let e;beforeEach(()=>{e=new LandmarkRecognitionEngine({landmarks:sampleLandmarks,minConfidence:.55})}),it("returns an exact match with full confidence",()=>{const a=e.identify(TAJ_HASH);expect(a.best.landmark.id).toBe("taj_mahal"),expect(a.best.confidence).toBe(1),expect(a.isConfident).toBe(!0)}),it("ranks matches best-first by distance",()=>{const a=e.identify(TAJ_HASH);expect(a.matches[0].landmark.id).toBe("taj_mahal"),expect(a.matches.length).toBe(2),expect(a.matches[0].distance).toBeLessThanOrEqual(a.matches[1].distance)}),it("flags low-confidence results as not confident",()=>{const a=TAJ_HASH.split("").map(e=>"1"===e?"0":"1").join(""),n=e.identify(a);expect(n.isConfident).toBe(!1)}),it("returns an error for an invalid query hash",()=>{const a=e.identify("not-a-hash");expect(a.error).toBe("invalid_hash"),expect(a.best).toBeNull()}),it("respects the topN option",()=>{const a=e.identify(TAJ_HASH,{topN:1});expect(a.matches.length).toBe(1)})}),describe("LandmarkRecognitionEngine history",()=>{let e;beforeEach(()=>{e=new LandmarkRecognitionEngine({landmarks:sampleLandmarks})}),it("adds valid entries to history, most recent first",()=>{e.addToHistory({landmarkId:"taj_mahal",landmarkName:"Taj Mahal",confidence:.9}),e.addToHistory({landmarkId:"hawa_mahal",landmarkName:"Hawa Mahal",confidence:.8});const a=e.getHistory();expect(a.length).toBe(2),expect(a[0].landmarkId).toBe("hawa_mahal")}),it("ignores entries without a landmarkId",()=>{expect(e.addToHistory({confidence:.9})).toBeNull(),expect(e.getHistory().length).toBe(0)}),it("caps history at the configured limit",()=>{for(let a=0;a<30;a++)e.addToHistory({landmarkId:`landmark_${a}`,landmarkName:`Landmark ${a}`});expect(e.getHistory().length).toBeLessThanOrEqual(25)}),it("clears history",()=>{e.addToHistory({landmarkId:"taj_mahal",landmarkName:"Taj Mahal"}),e.clearHistory(),expect(e.getHistory().length).toBe(0)})}),describe("LandmarkRecognitionEngine.getRelatedDestinations",()=>{it("falls back to curated nearbyAttractions when no destinations dataset is given",()=>{const e=LandmarkRecognitionEngine.getRelatedDestinations(sampleLandmarks[0]);expect(e.map(e=>e.name)).toEqual(["Agra Fort"])}),it("filters a destinations dataset by matching state",()=>{const e=LandmarkRecognitionEngine.getRelatedDestinations(sampleLandmarks[0],[{name:"Agra",state:"Uttar Pradesh",highlights:["Taj Mahal"]},{name:"Varanasi",state:"Uttar Pradesh",highlights:["Ganga Aarti"]},{name:"Jaipur",state:"Rajasthan",highlights:["Hawa Mahal"]}]);expect(e.map(e=>e.name)).toEqual(["Varanasi"])}),it("returns an empty array for a missing landmark",()=>{expect(LandmarkRecognitionEngine.getRelatedDestinations(null)).toEqual([])})});